  std::swap(PARAMETER_COUNT, o.PARAMETER_COUNT);
  std::swap(UPSERT_KEY_EXPRESSION, o.UPSERT_KEY_EXPRESSION);
  std::swap(RETENTION_MAX_RECORDS, o.RETENTION_MAX_RECORDS);
  std::swap(RETENTION_MAX_AGE_MILLIS, o.RETENTION_MAX_AGE_MILLIS);
  std::swap(COMPACTION_TARGET_BYTES, o.COMPACTION_TARGET_BYTES);
  std::swap(STATUS, o.STATUS);
  std::swap(AFFECTED_RECORDS, o.AFFECTED_RECORDS);
  std::swap(RESULT_BYTES, o.RESULT_BYTES);
