  { auto _e = TABLE_NAME(); if (_e) _o->TABLE_NAME = _e->str(); }
  { auto _e = INDEX_NAME(); if (_e) _o->INDEX_NAME = _e->str(); }
  { auto _e = INDEX_EXPRESSION(); if (_e) { _o->INDEX_EXPRESSION.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->INDEX_EXPRESSION.begin()); } }
  { auto _e = VIEW_NAME(); if (_e) _o->VIEW_NAME = _e->str(); }
  { auto _e = QUERY(); if (_e) { _o->QUERY.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->QUERY.begin()); } }
  { auto _e = PARAMETERS(); if (_e) { _o->PARAMETERS.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->PARAMETERS.begin()); } }
  { auto _e = PARAMETER_COUNT(); _o->PARAMETER_COUNT = _e; }
  { auto _e = UPSERT_KEY_EXPRESSION(); if (_e) { _o->UPSERT_KEY_EXPRESSION.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->UPSERT_KEY_EXPRESSION.begin()); } }
  { auto _e = RETENTION_MAX_RECORDS(); _o->RETENTION_MAX_RECORDS = _e; }
  { auto _e = RETENTION_MAX_AGE_MILLIS(); _o->RETENTION_MAX_AGE_MILLIS = _e; }
  { auto _e = COMPACTION_TARGET_BYTES(); _o->COMPACTION_TARGET_BYTES = _e; }
  { auto _e = STATUS(); _o->STATUS = _e; }
  { auto _e = AFFECTED_RECORDS(); _o->AFFECTED_RECORDS = _e; }
  { auto _e = RESULT_BYTES(); _o->RESULT_BYTES = _e; }
  { auto _e = ERROR_CODE(); if (_e) _o->ERROR_CODE = _e->str(); }
